selector_to_html = {"a[href=\"#term-style\"]": "<dt id=\"term-style\"><code class=\"docutils literal notranslate\"><span class=\"pre\">style</span></code></dt><dd><p>a change that only affects formatting, or a change related to the\nlinter configuration</p></dd>", "a[href=\"#commit-types\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Commit Types<a class=\"headerlink\" href=\"#commit-types\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#term-docs\"]": "<dt id=\"term-docs\"><code class=\"docutils literal notranslate\"><span class=\"pre\">docs</span></code></dt><dd><p>a documentation-only change, including edits to in-line\ndocumentation and comments</p></dd>", "a[href=\"#commit-messages\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Commit Messages<a class=\"headerlink\" href=\"#commit-messages\" title=\"Link to this heading\">#</a></h2><p>In commit messages:</p>", "a[href=\"#development-environment\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Development Environment<a class=\"headerlink\" href=\"#development-environment\" title=\"Link to this heading\">#</a></h2><p>Additionally, on Linux it needs\n<a class=\"reference external\" href=\"https://refspecs.linuxfoundation.org/lsb.shtml\">lsb-release</a>.  On\nmacOS it uses the\n<a class=\"reference external\" href=\"https://developer.apple.com/documentation/xcode/installing-the-command-line-tools\">Command Line Tools for Xcode</a>\nand <a class=\"reference external\" href=\"https://www.macports.org/\">MacPorts</a>.  Several of the available\nmake targets are listed below.  Review the\n<a class=\"github reference external\" href=\"https://github.com/ResearchDataCom/actions/blob/v4.0.0/GNUmakefile#\">makefile</a> for additional details.</p>", "a[href=\"#term-fix\"]": "<dt id=\"term-fix\"><code class=\"docutils literal notranslate\"><span class=\"pre\">fix</span></code></dt><dd><p>a bug fix</p></dd>", "a[href=\"#term-feat\"]": "<dt id=\"term-feat\"><code class=\"docutils literal notranslate\"><span class=\"pre\">feat</span></code></dt><dd><p>a new feature</p></dd>", "a[href=\"#term-perf\"]": "<dt id=\"term-perf\"><code class=\"docutils literal notranslate\"><span class=\"pre\">perf</span></code></dt><dd><p>a code change that improves performance</p></dd>", "a[href=\"#contribution-guidelines\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Contribution Guidelines<a class=\"headerlink\" href=\"#contribution-guidelines\" title=\"Link to this heading\">#</a></h1><p>The project practices <a class=\"reference external\" href=\"https://tdd.mooc.fi/\">test-driven development</a>\nin\n<a class=\"reference external\" href=\"https://www.atlassian.com/git/tutorials/comparing-workflows/feature-branch-workflow\">Git feature (topic) branches</a>.\nPlease maintain a <a class=\"reference external\" href=\"https://archive.is/VpWTs\">linear commit history</a> by\nrebasing changes on the latest HEAD of the main branch before\nsubmitting them for review as a\n<a class=\"reference external\" href=\"https://docs.github.com/en/pull-requests/collaborating-with-pull-requests\">GitHub pull request</a>.</p>", "a[href=\"#term-ci\"]": "<dt id=\"term-ci\"><code class=\"docutils literal notranslate\"><span class=\"pre\">ci</span></code></dt><dd><p>a change to continuous integration/continuous delivery (CI/CD)\nprocesses, e.g., GitHub Actions</p></dd>", "a[href=\"#term-refactor\"]": "<dt id=\"term-refactor\"><code class=\"docutils literal notranslate\"><span class=\"pre\">refactor</span></code></dt><dd><p>a code change that neither fixes a bug nor adds a feature</p></dd>", "a[href=\"#code-style\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Code Style<a class=\"headerlink\" href=\"#code-style\" title=\"Link to this heading\">#</a></h2><p>This project follows these code styles:</p>", "a[href=\"#term-chore\"]": "<dt id=\"term-chore\"><code class=\"docutils literal notranslate\"><span class=\"pre\">chore</span></code></dt><dd><p>a miscellaneous tooling or tool configuration change, e.g., the\n.gitignore file, or a change not covered by the other commit types</p></dd>", "a[href=\"#commit-scopes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Commit Scopes<a class=\"headerlink\" href=\"#commit-scopes\" title=\"Link to this heading\">#</a></h2><p>An atomic commit can alter multiple files.  For example, an interface\nchange could require modifications to class definitions, method calls,\nproperty references, and unit tests throughout the project.  The\ncommit scope tells reviewers where to focus their analysis.  In change\nlogs, commit scopes help sponsors understand the structure of the work\ngoing into fixes, features, or breaking changes.  Because actions\ninterface with one another (usually indirectly, via workflow artifacts\nor output/input conventions), commit scopes follow actions\u2019 base\nnames, e.g., <code class=\"docutils literal notranslate\"><span class=\"pre\">pre-commit</span></code>, not <code class=\"docutils literal notranslate\"><span class=\"pre\">actions/pre-commit</span></code>, nor\n<code class=\"docutils literal notranslate\"><span class=\"pre\">ResearchDataCom/actions/pre-commit</span></code>.</p>", "a[href=\"#term-test\"]": "<dt id=\"term-test\"><code class=\"docutils literal notranslate\"><span class=\"pre\">test</span></code></dt><dd><p>a new test or a correction to an existing test</p></dd>", "a[href=\"#term-build\"]": "<dt id=\"term-build\"><code class=\"docutils literal notranslate\"><span class=\"pre\">build</span></code></dt><dd><p>a change to the build system or external dependencies, e.g., the\nmakefile</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
